void Solver::bump_var(int var, double coeff) {
    double new_act = activity[var] + var_inc * coeff;
    activity[var] = new_act;
    if (new_act > 1e100) {
        // Rescale all activities to prevent floating point overflow
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    // Apply a small bonus based on current level to favor recently active vars
    if (level[var] > 0) {
        activity[var] += var_inc * coeff * 0.1 * (level[var] > 10 ? 10 : level[var]) / 10.0;
        if (activity[var] > 1e100) {
            for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
            var_inc *= 1e-100;
        }
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
// end

